using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using MakroSoundSwitch;
class ScrollSecurityVerify {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static void Assert(bool b,string m){if(!b)throw new Exception(m);Console.WriteLine("PASS: "+m);}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
 string file=Path.GetFullPath("security-test.xml");File.WriteAllText(file,"<!DOCTYPE Settings [<!ENTITY probe SYSTEM 'file:///must-not-be-read'>]><Settings><Scenarios/></Settings>");bool rejected=false;try{SettingsFile.Load(file);}catch{rejected=true;}Assert(rejected,"Settings loader rejects DTD and external entity declarations");File.WriteAllText(file,new string(' ',2097153));rejected=false;try{SettingsFile.Load(file);}catch{rejected=true;}Assert(rejected,"Oversized settings are rejected before XML parsing");File.WriteAllText(file,"<Settings><Scenarios><Scenario><Name>Original scenario</Name><Output>A</Output><Input>Z</Input></Scenario></Scenarios></Settings>");var loaded=SettingsFile.Load(file);Assert(loaded.Scenarios.Count==1&&Features.For(loaded.Scenarios[0]).Count==2,"Restricted XML loader retains old scenario compatibility");File.Delete(file);
 var scenario=new Scenario{Name="Long scenario",Chord=new List<int>{17,18,16,75,76,77,78,79},Features=Enumerable.Range(0,8).Select(i=>new ScenarioFeature{Type=FeatureType.PlayPauseMedia}).ToList()};
 using(var editor=new Editor(scenario,new List<Scenario>{scenario})){editor.Show();Application.DoEvents();var keys=(ScenarioList)typeof(Editor).GetField("keyRows",F).GetValue(editor);var features=(ScenarioList)typeof(Editor).GetField("featureRows",F).GetValue(editor);var overall=editor.Controls.OfType<Panel>().Single(p=>p.AutoScroll);Assert(!keys.AutoScroll&&!features.AutoScroll&&!keys.VerticalScroll.Visible&&!features.VerticalScroll.Visible,"Key and feature lists have no inner scrollbars");Assert(keys.Height>=8*40&&features.Height>=8*76,"Both lists grow to show every row");Assert(overall.VerticalScroll.Visible&&!overall.HorizontalScroll.Visible,"Only overall vertical scrolling is needed");var last=features.Controls[features.Controls.Count-1];overall.ScrollControlIntoView(last);Application.DoEvents();Assert(overall.AutoScrollPosition.Y<0,"Overall scroll reaches long feature list");Assert(editor.Controls.OfType<TableLayoutPanel>().Single().Controls.OfType<FlowLayoutPanel>().Single().Visible,"Save controls stay outside scrolling content");using(var b=new Bitmap(editor.Width,editor.Height)){editor.DrawToBitmap(b,new Rectangle(Point.Empty,editor.Size));b.Save("single-scroll-editor.png");}}
 string source=File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","src","SoundSwitch.cs"));Assert(!source.Contains(".GetData("),"Drag handling never deserializes external object data");Assert(source.Contains("DefaultDllImportSearchPaths(DllImportSearchPath.System32)"),"Native library imports restricted to System32");Assert(!source.Contains("--diagnostics"),"Device-ID diagnostics export removed from app");
 }
}

